/// <summary>
/// PaffH 29.09.25
/// </summary>
[DataContract]
class NDXBVEmailRequestRoleIdentificationContract
{
    FieldId fieldIdRoleIdentification;
    FieldId fieldIdRoleIdentificationStatus;
    FieldId fieldIdRoleLocalization;
    FieldId fieldIdDirPartyTableManual;
    FieldId fieldIdChangedManual;
    FieldId fieldIdBusRelAccount;
    FieldId fieldIdAssignedManual;
    FieldId fieldIdStreet;
    FieldId fieldIdZIPCode;
    Common tablebuffer;


}

Method.Source:
/// <summary>
/// PaffH 29.09.25
/// </summary>
/// <param name = "_common">Common</param>
/// <returns>NDXBVEmailRequestRoleIdentificationContract</returns>
public static NDXBVEmailRequestRoleIdentificationContract construct(Common _common)
{
    NDXBVEmailRequestRoleIdentificationContract contract = new NDXBVEmailRequestRoleIdentificationContract();
    contract.parmTablebuffer(_common);
    switch(_common.TableId)
    {
        case tableNum(NDXBVEMailRequestPlaner) :
            contract.parmFieldIdRoleIdentification(fieldNum(NDXBVEMailRequestPlaner, PlanerIdentification));
            contract.parmFieldIdRoleIdentificationStatus(fieldNum(NDXBVEMailRequestPlaner, PlanerIdentificationStatus));
            contract.parmFieldIdRoleLocalization(fieldNum(NDXBVEMailRequestPlaner, PlanerLocalization));
            contract.parmFieldIdDirPartyTableManual(fieldNum(NDXBVEMailRequestPlaner, DirPartyTableManual));
            contract.parmFieldIdChangedManual(fieldNum(NDXBVEMailRequestPlaner, PlanerChangedManual));
            contract.parmFieldIdBusRelAccount(fieldNum(NDXBVEMailRequestPlaner, ProspectProspectId));
            contract.parmFieldIdAssignedManual(fieldNum(NDXBVEMailRequestPlaner, Manual));
            contract.parmFieldIdStreet(fieldNum(NDXBVEMailRequestPlaner, AddressStreet));
            contract.parmFieldIdZIPCode(fieldNum(NDXBVEMailRequestPlaner, AddressZipCode));
            break;
        case tableNum(NDXBVEMailRequestInstaller) :
            contract.parmFieldIdRoleIdentification(fieldNum(NDXBVEMailRequestInstaller, PlumberIdentification));
            contract.parmFieldIdRoleIdentificationStatus(fieldNum(NDXBVEMailRequestInstaller, PlumberIdentificationStatus));
            contract.parmFieldIdRoleLocalization(fieldNum(NDXBVEMailRequestInstaller, PlumberLocalization));
            contract.parmFieldIdDirPartyTableManual(fieldNum(NDXBVEMailRequestInstaller, DirPartyTableManual));
            contract.parmFieldIdChangedManual(fieldNum(NDXBVEMailRequestInstaller, PlumberChangedManual));
            contract.parmFieldIdBusRelAccount(fieldNum(NDXBVEMailRequestInstaller, ProspectProspectId));
            contract.parmFieldIdAssignedManual(fieldNum(NDXBVEMailRequestInstaller, Manual));
            contract.parmFieldIdStreet(fieldNum(NDXBVEMailRequestInstaller, AddressStreet));
            contract.parmFieldIdZIPCode(fieldNum(NDXBVEMailRequestInstaller, AddressZipCode));
            break;
        default:
            Error(strFmt("@NDXBase:NDXTableIsNotTakenIntoAccountYet", _common.TableId));
    }
    return contract;
}

