/// <summary>
/// PaffH 29.09.25
/// </summary>
/// <param name = "_common">Common</param>
public void checkIdentification(Common _common = tablebuffer)
{
    if (!this.parmFieldIdRoleIdentification() ||
        !this.parmfieldIdRoleIdentificationStatus() ||
        !this.parmfieldIdRoleLocalization())
    {
        return;
    }
    _common.(this.parmFieldIdRoleIdentification()) = NDXBVEmailRequestRoleIdentification::LocalizationViaDataEntityFromOutlookPlugin;
    _common.(this.parmfieldIdRoleIdentificationStatus()) = NDXBVEmailRequestRoleIdentificationStatus::UnchangedAssignmentFromOutlookPlugin;
    _common.(this.parmfieldIdRoleLocalization()) = NDXBVEmailRequestRoleLocalization::LocalizationNotPossible;

    if (this.parmFieldIdDirPartyTableManual())
    {
        _common.(this.parmFieldIdRoleIdentification()) = NDXBVEmailRequestRoleIdentification::LocalizationManuallyInD365FO;
        _common.(this.parmfieldIdRoleLocalization()) = NDXBVEmailRequestRoleLocalization::LocalizationManuallyInD365FO;

        DirPartyTable dirPartyTable = DirPartyTable::findRec(_common.(this.parmFieldIdDirPartyTableManual()));
        LogisticsPostalAddress logisticsPostalAddress = LogisticsPostalAddress::findByLocation(dirPartyTable.PrimaryAddressLocation);
        if (dirPartyTable.PartyNumber == _common.(this.parmFieldIdBusRelAccount()))
        {
            _common.(this.parmFieldIdRoleIdentification()) = NDXBVEmailRequestRoleIdentification::LocalizationViaDataEntityFromOutlookPlugin;
            _common.(this.parmfieldIdRoleLocalization()) = NDXBVEmailRequestRoleLocalization::LocalizationNotPossible;
            _common.(this.parmFieldIdDirPartyTableManual()) = 0;
        }
        else if ((this.parmFieldIdStreet() && logisticsPostalAddress.Street == _common.(this.parmFieldIdStreet())) 
            && (this.parmFieldIdZIPCode() && logisticsPostalAddress.ZipCode == _common.(this.parmFieldIdZIPCode())))
        {
            _common.(this.parmfieldIdRoleIdentificationStatus()) = NDXBVEmailRequestRoleIdentificationStatus::StreetZipCodeOutlookPluginConform;
        }
        else
        {
            _common.(this.parmfieldIdRoleIdentificationStatus()) = NDXBVEmailRequestRoleIdentificationStatus::ChangedAssignmentInD365FO;
        }
    }
    if (this.parmFieldIdDirPartyTableManual() && _common.(this.parmFieldIdDirPartyTableManual()) == 0)
    {
        if (this.parmFieldIdChangedManual())
        {
            _common.(this.parmFieldIdChangedManual()) = NoYes::No;
        }
        if (this.parmFieldIdBusRelAccount() && _common.(this.parmFieldIdBusRelAccount()))
        {
            if (DirPartyTable::findByNum(_common.(this.parmFieldIdBusRelAccount())))
            {
                _common.(this.parmfieldIdRoleLocalization()) = NDXBVEmailRequestRoleLocalization::LocalizationViaOutlookPlugin;
            }
        }
        else
        {
            _common.(this.parmFieldIdRoleIdentification()) = NDXBVEmailRequestRoleIdentification::LocalizationViaEmailAnalysisViaOutlookPlugin;
        }
    }
    else
    {
        if (this.parmFieldIdChangedManual())
        {
            _common.(this.parmFieldIdChangedManual()) = NoYes::Yes;
        }
    }
    if (this.parmFieldIdAssignedManual() && _common.(this.parmFieldIdAssignedManual()) == NoYes::Yes)
    {
        _common.(this.parmFieldIdRoleIdentification()) = NDXBVEmailRequestRoleIdentification::ReassignmentInD365FO;
    }
}
